def render_threads_html(lang):
    if lang == 'en':
        with open('scratch/orig_seo_threads.html', 'r', encoding='utf-8') as f:
            return f.read()
    
    d = THREADS_DATA.get(lang)
    if not d:
        with open('scratch/orig_seo_threads.html', 'r', encoding='utf-8') as f:
            return f.read()
    
    t1_th = "".join(f"<th>{h}</th>" for h in d['t1_headers'])
    t1_tr = ""
    for r in d['t1_rows']:
        t1_tr += f"<tr><td><strong>{r[0]}</strong></td><td><code>{r[1]}</code></td><td>{r[2]}</td><td>{r[3]}</td></tr>"
        
    comp_th = "".join(f"<th>{h}</th>" for h in d['comp_headers'])
    comp_tr = ""
    for r in d['comp_rows']:
        comp_tr += f"<tr><td><strong>{r[0]}</strong></td><td><span class=\"badge-highlight\">{r[1]}</span></td><td>{r[2]}</td><td>{r[3]}</td><td>{r[4]}</td></tr>"
        
    html = f"""<div class="quick-answer" style="background: rgba(255,255,255,0.04); border-left: 4px solid #ffffff; padding: 18px 22px; border-radius: 8px; margin-bottom: 30px;">
    <h3 style="margin-top: 0; color: #ffffff; font-size: 1.15rem;"><i class="fas fa-bolt" style="color: #ffffff; margin-right: 8px;"></i> {d['qa_title']}</h3>
    <p style="margin-bottom: 0; font-size: 0.95rem; line-height: 1.6; color: #cbd5e1;">{d['qa_text']}</p>
</div>

<h2>{d['h2']}</h2>
<p>{d['intro']}</p>

<h3>{d['t1_h3']}</h3>
<div class="seo-table-container">
    <table class="seo-table">
        <thead>
            <tr>{t1_th}</tr>
        </thead>
        <tbody>
            {t1_tr}
        </tbody>
    </table>
</div>

<h3>{d['comp_h3']}</h3>
<p>{d['comp_p']}</p>

<div class="seo-table-container">
    <table class="seo-table">
        <thead>
            <tr>{comp_th}</tr>
        </thead>
        <tbody>
            {comp_tr}
        </tbody>
    </table>
</div>

<h3>{d['guide_h3']}</h3>
<ul>
    <li>{d['ios']}</li>
    <li>{d['android']}</li>
    <li>{d['pc']}</li>
</ul>

<h3>{d['priv_h3']}</h3>
<p>{d['priv_p']}</p>"""
    return html
